body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: #f6f8fc;
  color: #111827;
}

.admin-shell {
  padding: 18px;
  min-height: 100%;
  background: linear-gradient(135deg, rgba(124, 58, 237, 0.08), transparent 34%), linear-gradient(315deg, rgba(14, 165, 233, 0.08), transparent 30%), #f6f8fc;
}

.admin-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.admin-head h1 {
  margin: 0;
  font-size: 24px;
  font-weight: 850;
}

.admin-head p {
  margin: 5px 0 0;
  font-size: 13px;
  color: #64748b;
}

.print-btn {
  height: 38px;
  border: 0;
  border-radius: 8px;
  padding: 0 14px;
  font-weight: 800;
  background: #111827;
  color: #fff;
  cursor: pointer;
}

.admin-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(145px, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.kpi {
  background: #fff;
  border: 1px solid #e5e9f2;
  border-radius: 10px;
  padding: 14px;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.06);
}

.kpi span {
  display: block;
  font-size: 12px;
  color: #64748b;
  font-weight: 800;
  text-transform: uppercase;
}

.kpi strong {
  display: block;
  margin-top: 8px;
  font-size: 26px;
}

.kpi small {
  display: block;
  margin-top: 6px;
  color: #64748b;
  font-size: 12px;
}

.panel {
  background: #fff;
  border: 1px solid #e5e9f2;
  border-radius: 10px;
  padding: 14px;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.06);
  margin-bottom: 12px;
}

.panel-title {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  margin-bottom: 12px;
}

.panel-title h2 {
  margin: 0;
  font-size: 15px;
}

.issue-count {
  border-radius: 999px;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 900;
  background: #eef2ff;
  color: #3730a3;
}

.issue-list {
  display: grid;
  gap: 9px;
}

.issue-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border: 1px solid #e8edf5;
  border-radius: 10px;
  background: #fbfdff;
}

.issue-row strong {
  display: block;
  font-size: 13px;
}

.issue-row span {
  display: block;
  margin-top: 3px;
  color: #64748b;
  font-size: 12px;
}

.issue-row small {
  display: inline-flex;
  margin-top: 7px;
  font-size: 11px;
  color: #475569;
  font-weight: 800;
}

.badge {
  border-radius: 999px;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 900;
}

.high {
  border-color: #fecaca;
  background: #fff7f7;
}

.high .badge {
  background: #fee2e2;
  color: #b91c1c;
}

.medium {
  border-color: #fde68a;
  background: #fffbeb;
}

.medium .badge {
  background: #fef3c7;
  color: #92400e;
}

.low .badge {
  background: #e8eef8;
  color: #475569;
}

.empty {
  height: 120px;
  display: grid;
  place-items: center;
  border: 1px dashed #dbe3ef;
  border-radius: 10px;
  color: #94a3b8;
}

@media print {
  body,
  .admin-shell {
    background: #fff;
  }
  .admin-shell {
    padding: 0;
  }
  .print-btn {
    display: none;
  }
  .kpi,
  .panel {
    box-shadow: none;
    break-inside: avoid;
  }
}

