const root = document.getElementById("admin-control-center");
function n(value) {
  return Number(value || 0);
}
function esc(value) {
  return String(value ?? "").replace(/[&<>"']/g, char => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  })[char]);
}
function kpi(label, value, sub) {
  return `
    <div class="kpi">
      <span>${esc(label)}</span>
      <strong>${n(value).toLocaleString("en-US")}</strong>
      <small>${esc(sub || "")}</small>
    </div>
  `;
}
function issuesPanel(issues) {
  if (!issues.length) {
    return `
      <div class="panel">
        <div class="panel-title">
          <h2>Setup Issues</h2>
          <span class="issue-count">All clear</span>
        </div>
        <div class="empty">No administration setup issues found.</div>
      </div>
    `;
  }
  return `
    <div class="panel">
      <div class="panel-title">
        <h2>Setup Issues</h2>
        <span class="issue-count">${issues.length} issue groups</span>
      </div>

      <div class="issue-list">
        ${issues.map(row => `
          <div class="issue-row ${String(row.severity || "LOW").toLowerCase()}">
            <div>
              <strong>${esc(row.title || "")}</strong>
              <span>${esc(row.detailText || "")}</span>
              <small>${esc(row.moduleName || "")} · ${n(row.countValue)} item(s)</small>
            </div>
            <div class="badge">${esc(row.severity || "LOW")}</div>
          </div>
        `).join("")}
      </div>
    </div>
  `;
}
function render() {
  const model = appsmith.model || {};
  const s = model.summary || {};
  const issues = model.issues || [];
  root.innerHTML = `
    <div class="admin-shell">
      <div class="admin-head">
        <div>
          <h1>Administration Control Center</h1>
          <p>${esc(model.companyName)} · Updated ${esc(model.generatedAt)} · ${esc(model.username)}</p>
        </div>
        <button id="print-admin" class="print-btn">Print</button>
      </div>

      <div class="admin-kpis">
        ${kpi("Active users", s.activeUsers, `${n(s.usersWithoutRoles)} without roles`)}
        ${kpi("Branches", s.activeBranches, `${n(s.branchesWithoutWarehouse)} without warehouse`)}
        ${kpi("Cash registers", s.activeCashRegisters, `${n(s.incompleteCashRegisters)} incomplete`)}
        ${kpi("Audit 24h", s.auditEventsLast24h, "Administration and system changes")}
      </div>

      <div class="admin-kpis">
        ${kpi("Document types", s.activeDocumentTypes, "Active document setup")}
        ${kpi("Payment methods", s.activePaymentMethods, "Active payment setup")}
        ${kpi("Sales plans", s.salesPlans, "Planning records")}
        ${kpi("System roles", s.systemRoles, "Core ERP roles")}
      </div>

      ${issuesPanel(issues)}
    </div>
  `;
  document.getElementById("print-admin").onclick = () => window.print();
}
appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});

